  const idToken = req.cookies.idToken;
  const claims = decodeJwtPayload(idToken);
  if (!claims.email || !claims.sub) {
    return { valid: false, reason: 'Missing user claims' };
  }

  return {
    valid: true,
    accessToken,
    idToken,
    claims,
  };
}

