    .card { border: 1px solid #d1d5db; border-radius: 0.75rem; padding: 1rem; margin: 1rem 0; background: #f9fafb; }
    code { background: #eef2ff; padding: 0.15rem 0.35rem; border-radius: 0.25rem; }
  </style>
