        .then((user) => {
          document.getElementById('user-email').textContent = user.email;
          document.getElementById('user-sub').textContent = user.sub;
        })
        .catch((error) => console.error(error));
    </script>
  `));
});

app.get('/api/me', requireValidSession({ json: true }), (req, res) => {
